1	/**
2	 * Audio player re-mount idempotency tests.
3	 *
4	 * Regression tests for the sleeping-mobile-wake bug: when the LiveView
5	 * WebSocket times out during a long phone sleep, the server-side LV
6	 * process is GC'd. On wake the client does a fresh mount with a new LV
7	 * process, which fires `destroyed` then `mounted` on every hook —
8	 * including the audio player.
9	 *
10	 * The <audio> element survives this cycle thanks to phx-update="ignore".
11	 * If the hook re-runs `audio.src = ...; audio.load()` on every mount,
12	 * it stomps the prefetched blob URL the user is currently listening to,
13	 * triggers a refetch from a still-suspended network, and strands the
14	 * user at 00:00/00:00 with a dead play button.
15	 *
16	 * The fix makes mount idempotent: skip the src reset if the audio
17	 * element already has a meaningful src. These tests pin that behavior.
18	 *
19	 * Requires the canonical e2e fixture: at least one chapter with audio
20	 * (default `audio_for: [1, 2]` in `ReadaloudAudiobook.Fixtures.E2E.seed!/1`).
21	 */
22	import { describe, it, before, after } from "node:test";
23	import assert from "node:assert";
24	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
25	
26	describe("Audio player re-mount idempotency", () => {
27		let browser, page;
28	
29		before(async () => {
30			({ browser, page } = await setup());
31	
32			await openReader(page);
33			const chapters = await page.evaluate(() => {
34				const bar = document.getElementById("chapter-bar");
35				return bar ? JSON.parse(bar.dataset.chapters) : [];
36			});
37			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
38			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
39			assert.ok(
40				chapters.length > 0,
41				"fixture must seed ≥1 chapter; check ReadaloudAudiobook.Fixtures.E2E.seed!/1",
42			);
43	
44			let found = false;
45			for (const ch of chapters) {
46				await page.goto(
47					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
48					{ waitUntil: "networkidle2" },
49				);
50				await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
51				await page.waitForSelector("#chapter-text", { timeout: 10000 });
52				const player = await page
53					.waitForSelector("#audio-player", { timeout: 1000 })
54					.catch(() => null);
55				if (player) {
56					found = true;
57					break;
58				}
59			}
60			assert.ok(
61				found,
62				"fixture must seed ≥1 audio-ready chapter; check `audio_for` " +
63					"in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
64			);
65		});
66	
67		after(async () => {
68			await teardown(browser);
69		});
70	
71		it("audio.src is preserved when the hook is destroyed and re-mounted", async () => {
72			// Wait for the initial mount to actually set audio.src.
73			await page.waitForFunction(
74				() => {
75					const a = document.getElementById("audio-element");
76					return a && a.src && a.src.includes("/api/books/");
77				},
78				{ timeout: 5000 },
79			);
80	
81			// Replace the live audio src with a sentinel value. This stands in
82			// for "user is mid-playback on a prefetched blob URL when the LV
83			// times out" — what matters for the bug is that the src is some
84			// non-empty value that the *server* did not put there.
85			const sentinelSrc = `blob:${BASE_URL}/sentinel-${Date.now()}`;
86			await page.evaluate((src) => {
87				const a = document.getElementById("audio-element");
88				a.src = src;
89			}, sentinelSrc);
90	
91			const beforeSrc = await page.$eval("#audio-element", (el) => el.src);
92			assert.strictEqual(beforeSrc, sentinelSrc, "sanity: sentinel applied");
93	
94			// Detach and re-attach the player div. Phoenix LV's MutationObserver
95			// detects this and runs `destroyed` on removal followed by `mounted`
96			// on insertion — the same lifecycle the bug triggers on a real
97			// post-sleep reconnect with a dead server-side LV process.
98			await page.evaluate(() => {
99				const el = document.getElementById("audio-player");
100				window.__remountSaved = {
101					el,
102					parent: el.parentNode,
103					nextSibling: el.nextSibling,
104				};
105				el.remove();
106			});
107	
108			// Wait for the MutationObserver to actually flush the removal —
109			// observable as #audio-player being gone from the DOM. Without this
110			// gap, destroy and mount can collapse into a single flush and
111			// short-circuit the lifecycle we're trying to exercise.
112			await page.waitForFunction(
113				() => document.getElementById("audio-player") === null,
114				{ timeout: 1000 },
115			);
116	
117			await page.evaluate(() => {
118				const { el, parent, nextSibling } = window.__remountSaved;
119				parent.insertBefore(el, nextSibling);
120				delete window.__remountSaved;
121			});
122	
123			// Wait for the re-mount to complete — the audio-player div is back.
124			await page.waitForSelector("#audio-player", { timeout: 5000 });
125	
126			const afterSrc = await page.$eval("#audio-element", (el) => el.src);
127			assert.strictEqual(
128				afterSrc,
129				sentinelSrc,
130				"audio.src must survive a hook destroy/mount cycle — without " +
131					"this, sleeping-mobile autoplay re-stalls on wake when LV " +
132					"reconnects with a fresh process",
133			);
134		});
135	
136		it("audio.currentTime is preserved across destroy/mount (proves load() was not called)", async () => {
137			// Restore real audio src (previous test left a sentinel) and wait
138			// for metadata so we have a valid duration to seek into.
139			await page.evaluate(() => {
140				const a = document.getElementById("audio-element");
141				const player = document.getElementById("audio-player");
142				a.src = player.dataset.audioUrl;
143				a.load();
144			});
145			await page.waitForFunction(
146				() => {
147					const a = document.getElementById("audio-element");
148					return a && Number.isFinite(a.duration) && a.duration > 0;
149				},
150				{ timeout: 10000 },
151			);
152	
153			// Seek to a distinctive non-zero time. The OLD code's destroy →
154			// mount cycle called `audio.src = url; audio.load()` on mount,
155			// and load() resets currentTime to 0. The NEW code skips that
156			// when src is already set, so currentTime survives.
157			const SEEK_SECONDS = 7.5;
158			await page.evaluate((t) => {
159				const a = document.getElementById("audio-element");
160				a.currentTime = t;
161			}, SEEK_SECONDS);
162			// `currentTime =` is synchronous on the element, but the seeking
163			// state takes a frame to settle. Wait for the seek to commit.
164			await page.waitForFunction(
165				(target) => {
166					const a = document.getElementById("audio-element");
167					return a && Math.abs(a.currentTime - target) < 1;
168				},
169				{ timeout: 2000 },
170				SEEK_SECONDS,
171			);
172	
173			const beforeTime = await page.$eval(
174				"#audio-element",
175				(el) => el.currentTime,
176			);
177			assert.ok(
178				Math.abs(beforeTime - SEEK_SECONDS) < 1,
179				`sanity: currentTime should be near ${SEEK_SECONDS}, got ${beforeTime}`,
180			);
181	
182			// Re-mount cycle.
183			await page.evaluate(() => {
184				const el = document.getElementById("audio-player");
185				window.__remountSaved = {
186					el,
187					parent: el.parentNode,
188					nextSibling: el.nextSibling,
189				};
190				el.remove();
191			});
192			await page.waitForFunction(
193				() => document.getElementById("audio-player") === null,
194				{ timeout: 1000 },
195			);
196			await page.evaluate(() => {
197				const { el, parent, nextSibling } = window.__remountSaved;
198				parent.insertBefore(el, nextSibling);
199				delete window.__remountSaved;
200			});
201			await page.waitForSelector("#audio-player", { timeout: 5000 });
202	
203			const afterTime = await page.$eval(
204				"#audio-element",
205				(el) => el.currentTime,
206			);
207			// audio.load() resets currentTime to 0; if the hook called it on
208			// mount (the regression), this drops to ~0. Allow a small window
209			// for natural drift if the audio happened to be playing.
210			assert.ok(
211				Math.abs(afterTime - SEEK_SECONDS) < 1.5,
212				`currentTime should survive re-mount (was ${beforeTime}, now ${afterTime}). ` +
213					`If this drops to ~0, the hook is calling audio.load() on re-mount, ` +
214					`which is the sleeping-mobile-wake regression.`,
215			);
216		});
217	
218		it("the mount-time idempotency heuristic accepts blob: and network URLs", async () => {
219			// This is a documentation-of-contract test. The hook decides
220			// "should I reset audio.src on mount?" based on whether the
221			// existing src is meaningful. If you change the heuristic in
222			// audio_player.ts, update this test too — and think hard about
223			// whether the change breaks the sleeping-mobile-wake invariant.
224			const verdicts = await page.evaluate(() => {
225				const a = document.createElement("audio");
226				const samples = [
227					"",
228					window.location.href,
