/**
 * Autoplay regression: LV WebSocket disconnect during chapter boundary.
 *
 * Reproduces the mobile-screen-locked bug Noah hit in production:
 *
 *   - Listening on chapter N. Phone screen locks. The OS keeps the
 *     <audio> element playing via the Media Session, but the LV
 *     WebSocket is suspended/torn down.
 *   - Audio plays to the end of N. The hook's `ended` listener fires
 *     and JS-side swaps audio.src to chapter N+1 (using the prefetched
 *     blob). audio.play() succeeds — playback continues briefly into
 *     N+1 over the lock screen.
 *   - The hook ALSO calls `pushEvent("next_chapter")` so the server
 *     can push_patch the URL. With the socket dead, that event is
 *     dropped on the floor.
 *   - User wakes the phone. LV reconnects with a fresh process and
 *     re-mounts on the URL it sees, which is still chapter N. The
 *     audio element survives (phx-update="ignore") and audio.src is
 *     still chapter N+1's blob. State is now permanently inconsistent:
 *     URL says N, audio plays N+1, and the user has to refresh and
 *     manually navigate to N+1 to recover.
 *
 * Invariant this test pins: after `ended` + autoplay, however the LV
 * socket behaves around the chapter boundary, the URL must eventually
 * agree with the chapter audio.src points at. Either push_patch lands
 * (the desired fix), or audio.src reverts to match the URL — but the
 * two must NOT diverge permanently.
 */
import { describe, it, before, after } from "node:test";
import assert from "node:assert";
import { setup, teardown, openReader, BASE_URL } from "../helpers.js";

describe("Audio autoplay across LV disconnect", () => {
	let browser, page;

	before(async () => {
		({ browser, page } = await setup());

		// Walk to the first chapter that has both audio AND a next-audio
		// chapter (same precondition as audio-autoplay.test.js).
		await openReader(page);
		const chapters = await page.evaluate(() => {
			const bar = document.getElementById("chapter-bar");
			return bar ? JSON.parse(bar.dataset.chapters) : [];
		});
		const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
		assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
		assert.ok(chapters.length > 0, "fixture must seed ≥1 chapter");

		let found = false;
		for (const ch of chapters) {
			await page.goto(
				`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
				{ waitUntil: "networkidle2" },
			);
			await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
			await page.waitForSelector("#chapter-text", { timeout: 10000 });
			const player = await page
				.waitForSelector("#audio-player", { timeout: 1000 })
				.catch(() => null);
			if (player) {
				const nextUrl = await page.$eval(
					"#audio-player",
					(el) => el.dataset.nextAudioUrl || "",
				);
				if (nextUrl) {
					found = true;
					break;
				}
			}
		}
		assert.ok(
			found,
			"fixture must seed ≥2 contiguous audio-ready chapters; check " +
				"`audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
		);

		// Enable autoplay and reload so the hook's PersistedRecord cache
		// picks up the new value on its next mount.
		await page.evaluate(() => {
			const cur = (() => {
				try {
					return JSON.parse(
						localStorage.getItem("readaloud-reader-settings") || "{}",
					);
				} catch {
					return {};
				}
			})();
			cur.autoNextChapter = true;
			localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
		});
		await page.reload({ waitUntil: "networkidle2" });
		await page.waitForSelector("#audio-element", { timeout: 10000 });
		// Wait for the hook to apply its initial src so we have something
		// to swap away from.
		await page.waitForFunction(
			() => {
				const a = document.getElementById("audio-element");
				return a?.src && a.src.includes("/api/books/");
			},
			{ timeout: 5000 },
		);
	});

	after(async () => {
		await teardown(browser);
	});

	it("URL eventually agrees with audio.src after ended fires while socket is disconnected", async () => {
		const before = await page.evaluate(() => {
			const player = document.getElementById("audio-player");
			return {
				url: window.location.pathname,
				chapterId: player?.dataset.chapterId,
				nextChapterId: player?.dataset.nextChapterId,
				nextAudioUrl: player?.dataset.nextAudioUrl,
			};
		});
		assert.ok(before.nextChapterId, "must have a next chapter to swap to");
		assert.notStrictEqual(
			before.chapterId,
			before.nextChapterId,
			"sanity: next chapter id must differ from current",
		);

		// Simulate the phone going to sleep: kill the LV WebSocket. The
		// <audio> element keeps playing (in real life via the OS Media
		// Session); JS in the page keeps running.
		await page.evaluate(() => {
			window.liveSocket.disconnect();
		});
		await page.waitForFunction(() => !window.liveSocket.isConnected(), {
			timeout: 5000,
		});

		// Audio plays to the end of the current chapter while the socket
		// is dead. The hook's `ended` listener fires and JS-side swaps
		// audio.src to the next chapter (this part doesn't need the
		// server). It also pushEvent("next_chapter") — which is the event
		// that gets dropped because the socket is closed.
		await page.evaluate(() => {
			const a = document.getElementById("audio-element");
			a.dispatchEvent(new Event("ended"));
		});

		// Verify the JS-side swap fired — audio.src no longer points at
		// the current chapter. (If this fails, the bug isn't what we
		// think; the swap is short-circuiting before the socket-drop
		// matters.)
		await page.waitForFunction(
			(currentChapterId) => {
				const a = document.getElementById("audio-element");
				if (!a?.src) return false;
				return !a.src.endsWith(`/chapters/${currentChapterId}/audio`);
			},
			{ timeout: 3000 },
			before.chapterId,
		);

		// Phone wakes: LV reconnects with a fresh server-side process.
		await page.evaluate(() => {
			window.liveSocket.connect();
		});
		await page.waitForFunction(() => window.liveSocket.isConnected(), {
			timeout: 10000,
		});

		// Give the server a beat to settle: any post-reconnect mount
		// roundtrips, push_patch deliveries, etc. should land within this
		// window. If the URL is going to update, it'll update by now.
		await new Promise((r) => setTimeout(r, 2000));

		const after = await page.evaluate(() => {
			const a = document.getElementById("audio-element");
			return {
				url: window.location.pathname,
				audioSrc: a?.src ?? null,
			};
		});

		const urlChapterId = after.url.match(/\/read\/(\d+)/)?.[1];
		assert.ok(urlChapterId, `URL should match /read/(N), got ${after.url}`);

		// audio.src may be a blob: URL prefetched from the next chapter,
		// or the network URL fallback. Either way we can identify which
		// chapter it represents — blob URLs are opaque, but we know the
		// hook only swaps to dataset.nextAudioUrl, so a blob src means
		// "audio is playing the chapter that WAS the next chapter".
		const audioIsBlob = after.audioSrc?.startsWith("blob:");
		const audioMatchesUrl = after.audioSrc?.endsWith(
			`/chapters/${urlChapterId}/audio`,
		);
		const audioIsNextChapter = audioIsBlob
			? // blob src came from prefetch → it's the next chapter
				true
			: after.audioSrc?.endsWith(`/chapters/${before.nextChapterId}/audio`);

		// THE INVARIANT: URL and audio.src must agree on which chapter
		// the user is on. Two acceptable outcomes:
		//   1. URL advanced to next chapter  (push_patch landed somehow)
		//   2. audio reverted to current     (server re-asserted the URL chapter)
		// The bug is the third outcome: URL=N, audio plays N+1, forever.
		const inSync =
			urlChapterId === before.nextChapterId || // URL caught up
			audioMatchesUrl; // OR audio reverted to URL chapter

		assert.ok(
			inSync,
			"URL and audio.src diverged after ended-during-disconnect:\n" +
				`  url chapter:        ${urlChapterId} (was ${before.chapterId})\n` +
				`  audio.src:          ${after.audioSrc}\n` +
				`  audioIsBlob:        ${audioIsBlob}\n` +
				`  audioIsNextChapter: ${audioIsNextChapter}\n` +
				`  expected next:      ${before.nextChapterId}\n` +
				"This is the mobile-lock-screen autoplay bug: the JS-side " +
				"swap happened but the server never push_patched the URL " +
				"because the next_chapter event was dropped by the dead " +
				"socket. After reconnect the LV remounts on the stale URL " +
				"and the user is stranded with audio playing one chapter, " +
				"URL pointing at another.",
		);
	});
});

