		// Simulate the phone going to sleep: kill the LV WebSocket. The
		// <audio> element keeps playing (in real life via the OS Media
		// Session); JS in the page keeps running.
		await page.evaluate(() => {
			window.liveSocket.disconnect();
		});
		await page.waitForFunction(() => !window.liveSocket.isConnected(), {
			timeout: 5000,
		});

